function iconFor(s){
  s=String(s||'');
  if(/색상|컬러|도금|크롬/.test(s))return SVG.color;
  if(/태엽|견고|구조/.test(s))return SVG.gear;
  if(/유형|옵션|다양/.test(s))return SVG.layers;
  if(/LED|조명|등/.test(s))return SVG.bulb;
  if(/길이/.test(s))return SVG.ruler;
  if(/유연|부드/.test(s))return SVG.wave;
  if(/안전/.test(s))return SVG.shield;
  if(/작동|회전/.test(s))return SVG.rotate;
  if(/디자인|세련|고급|프리미엄/.test(s))return SVG.sparkle;
  if(/모던/.test(s))return SVG.grid;
  if(/클래식/.test(s))return SVG.diamond;
  if(/레트로/.test(s))return SVG.clock;
  return SVG.sparkle;
}

