// product name with its own finish token removed → identifies the physical product (shape)
function baseOf(it){return (it.finish?it.name.split(it.finish).join(''):it.name).replace(/\s+/g,' ').trim();}
// real color/finish label: skip structural labels (cat/mid/grp); many 도금 rows store 마감==중분류,
// so fall back to the last meaningful tag (the actual plating color) or the last name token
function colorOf(it){
  const struct=new Set([it.cat,it.mid,it.grp,'']);
  if(it.finish && !struct.has(it.finish)) return it.finish;
  const tg=it.tags||[];
  for(let i=tg.length-1;i>=0;i--){ if(!struct.has(tg[i])) return tg[i]; }
  const toks=(it.name||'').split(/\s+/).filter(Boolean);
  return toks.length?toks[toks.length-1]:'';
}
